const enc=async u8=>{const iv=crypto.getRandomValues(new Uint8Array(12)),ct=await crypto.subtle.encrypt({name:'AES-GCM',iv},await key(true),u8);return{iv,ct}};
const dec=async r=>new Uint8Array(await crypto.subtle.decrypt({name:'AES-GCM',iv:r.iv},await key(false),r.ct));
const img=file=>new Promise((res,rej)=>{const u=URL.createObjectURL(file),i=new Image();i.onload=()=>{URL.revokeObjectURL(u);res(i)};i.onerror=()=>{URL.revokeObjectURL(u);rej(new Error('Imaginea nu poate fi citită. Încearcă o poză JPEG sau PNG.'))};i.src=u});
