  const m=await shrink(im,1800,.78),t=await shrink(im,260,.7);
  await put('b:'+id,{...(await enc(new Uint8Array(await buf(m.b)))),mime:'image/jpeg'});await put('t:'+id,{...(await enc(new Uint8Array(await buf(t.b)))),mime:'image/jpeg'});
