bar=(p,c)=>`<div class="bar"><i style="width:${Math.max(0,Math.min(100,p||0))}%;${c?'background:'+c:''}"></i></div>`,
ago=(d,t)=>{const m=Math.round((Date.now()-dts(d,t).getTime())/6e4);if(m<1)return'chiar acum';if(m<60)return`acum ${m} min`;if(m<1440)return`acum ${Math.floor(m/60)} h`;const z=Math.floor(m/1440);return z===1?'ieri':`acum ${z} zile`},
