 if(mode==='gray'){let lo=255,hi=0;const h=new Uint32Array(256);g.forEach(v=>h[v]++);let c=0;const n=g.length;for(let v=0;v<256;v++){c+=h[v];if(lo===255&&c>n*.01)lo=v;if(c>n*.99){hi=v;break}}const k=255/Math.max(1,hi-lo);for(let j=0;j<g.length;j++){const v=Math.max(0,Math.min(255,(g[j]-lo)*k));d[j*4]=d[j*4+1]=d[j*4+2]=v}cx.putImageData(im,0,0);return new Promise(r=>cv.toBlob(r,'image/png'))}
 /* Bradley adaptive threshold cu imagine integrală */
 const I=new Float64Array((W+1)*(H+1));for(let y=0;y<H;y++){let row=0;for(let x=0;x<W;x++){row+=g[y*W+x];I[(y+1)*(W+1)+x+1]=I[y*(W+1)+x+1]+row}}
