function vpForm(x){const o=x||{};ask(x?'Editează vizita':'Pregătește o vizită',[{n:'date',l:'Data',t:'date',v:o.date||today(),req:1},{n:'time',l:'Ora',t:'time',v:o.time||''},{n:'doctor',l:'Medic',v:o.doctor||(P().doctor||'')},{n:'spec',l:'Specialitate',v:o.spec||'',ph:'ex. Cardiologie'},{n:'qs',l:'Întrebările mele (câte una pe rând)',t:'area',v:o.qs||'',w:1}],v=>{const e=x||{id:id(),pid,reason:'',concl:'',next:''};Object.assign(e,{planned:true,date:v.date,time:v.time||'',doctor:(v.doctor||'').trim(),spec:(v.spec||'').trim(),qs:(v.qs||'').trim()});if(!x)data.visits.push(e);save()})}
