/* ---- cronologie ---- */
function tlEvents(p){const E=[];
 data.dx.filter(x=>x.pid===p&&x.date).forEach(x=>E.push({d:x.date,t:'dx',i:'🩺',h:'Diagnostic: '+x.name,s:[x.code,x.doctor,x.status==='rezolvat'?'rezolvat':''].filter(Boolean).join(' · '),go:'dx'}));
 const lb={};data.labs.filter(x=>x.pid===p&&x.date).forEach(x=>(lb[x.date]=lb[x.date]||[]).push(x));
 Object.entries(lb).forEach(([d,a])=>{const bad=a.filter(x=>labFlag(x)!=='N');E.push({d,t:'lab',i:'🧪',h:`Analize (${a.length} ${a.length===1?'valoare':'valori'})`,s:bad.length?`${bad.length} în afara limitelor: `+bad.slice(0,4).map(x=>x.t).join(', '):'toate în limite',go:'lab',bad:bad.length>0})});
 data.docs.filter(x=>x.pid===p&&x.date).forEach(x=>E.push({d:x.date,t:'doc',i:'📄',h:x.title,s:[DOCK[x.kind],(x.files||[]).length?(x.files.length+' fișiere'):''].filter(Boolean).join(' · '),go:'doc'}));
 data.visits.filter(x=>x.pid===p&&x.date).forEach(x=>E.push({d:x.date,t:'vis',i:x.planned?'📅':'👨‍⚕️',h:(x.planned?'Vizită planificată: ':'Consultație: ')+(x.spec||x.doctor||'medic'),s:x.concl||x.reason||'',go:'vis'}));
 data.prev.filter(x=>x.pid===p&&x.last).forEach(x=>E.push({d:x.last,t:'prev',i:'🛡️',h:'Efectuat: '+x.name,s:PK[x.kind]||'',go:'prev'}));
 data.meds.filter(x=>x.pid===p&&x.start).forEach(x=>E.push({d:x.start,t:'med',i:'💊',h:'Început tratament: '+x.name+(x.dose?' '+x.dose:''),s:x.prn?'la nevoie':(x.times||[]).join(', '),go:'med'}));
 return E.sort((a,b)=>b.d.localeCompare(a.d))}
const TLF=[['','Toate'],['dx','Diagnostice'],['lab','Analize'],['doc','Documente'],['vis','Vizite'],['prev','Prevenție'],['med','Tratament']];
DOS.time=()=>{const E=tlEvents(pid).filter(e=>!tlF||e.t===tlF);let m='',h='';
 E.forEach(e=>{const k=e.d.slice(0,7);if(k!==m){m=k;h+=`<div class="mh">${MONTHS[+k.slice(5,7)-1]} ${k.slice(0,4)}</div>`}h+=`<button class="tle" ${e.go==='med'?'data-go="meds"':`data-dt="${e.go}"`}><span class="td ${e.bad?'bad':''}">${e.i}</span><span style="flex:1;min-width:0"><b>${esc(e.h)}</b><small>${fmtD(e.d)}${e.s?' · '+esc(e.s):''}</small></span><span class="mu">›</span></button>`});
 return`<div class="card"><h2>Cronologie</h2><small class="mu">Tot ce s-a întâmplat cu sănătatea ta, în ordine. Atinge un rând ca să deschizi secțiunea.</small><div class="seg sc" style="margin-top:10px">${TLF.map(([k,n])=>`<button class="${tlF===k?'on':''}" data-tlf="${k}">${n}</button>`).join('')}</div>${h||'<div class="empty">Nimic de arătat încă. Adaugă diagnostice, analize, documente sau consultații.</div>'}</div>`};
/* ---- fișa PDF pentru vizită ---- */
async function buildVisit(v){await loadPdf();const p=P(),a=age(p),t=today(),from=addD(t,-30),pd=new Pdf(`Fișă vizită · ${pname(p)} · ${fmtD(t)}`);
 pd.title('Fișă pentru vizita la medic',`${pname(p)} · ${fmtD(v.date||t)}${v.time?' '+v.time:''}${v.spec?' · '+v.spec:''}${v.doctor?' · '+v.doctor:''}`);
 const w=vlast(pid,'weight'),ix=indices(pid);
 pd.h2('Pacient');pd.kv([['Nume',pname(p)],['Vârstă / sex',[a!=null?a+' ani':'',SEX[p.sex]].filter(Boolean).join(' · ')],['Înălțime / greutate',[p.height&&p.height+' cm',w&&w.v+' kg'].filter(Boolean).join(' / ')],['IMC',ix&&ix.bmi?r1(ix.bmi)+' kg/m²':''],['Grupa de sânge',p.blood],['Fumat / alcool',[({nu:'nefumător',fost:'fost fumător',da:'fumător'})[p.smoke],({deloc:'fără alcool',ocazional:'alcool ocazional',moderat:'alcool moderat',frecvent:'alcool frecvent'})[p.alc]].filter(Boolean).join(' · ')]]);
 if(p.allergies||p.intol)pd.box('Alergii / intoleranțe: '+[p.allergies,p.intol].filter(Boolean).join(' · '));
 const qs=(v.qs||'').split('\n').map(s=>s.trim()).filter(Boolean);if(qs.length){pd.h2('Întrebările mele');pd.p(qs.map((q,i)=>`${i+1}. ${q}`).join('\n'),10.5)}
 const dxa=data.dx.filter(x=>x.pid===pid&&x.status!=='rezolvat');if(dxa.length){pd.h2('Diagnostice active');pd.p(dxa.map(x=>'• '+x.name+(x.code?' ('+x.code+')':'')+(x.date?', din '+fmtD(x.date):'')).join('\n'),10)}
 const ms=data.meds.filter(m=>m.pid===pid&&(!m.end||m.end>=t));if(ms.length){pd.h2('Tratament curent');pd.table(['Medicament','Doză','Program'],ms.map(m=>[{t:m.name,b:1},m.dose||'',m.prn?'la nevoie':(m.times||[]).join(', ')+' · '+dnames(m)]),[5,2.5,5]);const ad=adh(pid,from,t);if(ad.exp)pd.p(`Aderență în ultimele 30 de zile: ${r0(ad.pct)}% (${ad.taken} luate, ${ad.skip} sărite, ${ad.miss} ratate).`,9.5)}
 const bps=pbp(pid,from,t);pd.h2('Tensiune, ultimele 30 de zile');if(bps.length){const s=bpStats(bps,pid),tg=tgt(pid);pd.kv([['Măsurători',`${s.n} în ${s.days} zile`],['Medie',`${r0(s.sys)}/${r0(s.dia)} mmHg`],['Sistolică min–max',`${s.smin}–${s.smax}`],['Diastolică min–max',`${s.dmin}–${s.dmax}`],['Puls mediu',s.pn?r0(s.pulse)+' bpm':''],[`Sub ținta ${tg.sys}/${tg.dia}`,`${r0(s.inT/s.n*100)}%`]]);await pd.chart(bpChart(bps,pid,from,t));insights(pid,from,t).forEach(([,h])=>pd.p('• '+plain(h),9.2))}else pd.p('Nu există măsurători în ultimele 30 de zile.',9.5);
 const L=data.labs.filter(x=>x.pid===pid).sort((x,y)=>x.date.localeCompare(y.date)),last={};L.forEach(x=>last[x.t]=x);const lr=Object.values(last).filter(x=>labFlag(x)!=='N'||x.date>=addD(t,-120)).sort((x,y)=>(labFlag(x)==='N')-(labFlag(y)==='N')||y.date.localeCompare(x.date));
 if(lr.length){pd.h2('Analize recente sau în afara limitelor');pd.table(['Analiza','Valoare','Referință','Data','Stare'],lr.map(x=>{const f=labFlag(x);return[{t:x.t,b:1},{t:`${x.v} ${x.u||''}`,b:1},labRef(x)+' '+(x.u||''),fmtD(x.date),f==='H'?{t:'↑ crescut',b:1,c:[200,30,50]}:f==='L'?{t:'↓ scăzut',b:1,c:[200,30,50]}:{t:'în limite',c:[20,120,80]}]}),[5,2.5,3,2,2.2])}
 const sy=lf(pid,'sym',from,t).sort((x,y)=>y.date.localeCompare(x.date));if(sy.length){pd.h2('Simptome notate (30 de zile)');pd.table(['Data','Simptom','Intensitate','Notă'],sy.map(x=>[fmtD(x.date),{t:x.t,b:1},['','ușor','moderat','sever'][x.sev||1],x.note||'']),[2.2,4,2,6])}
 const wk=wstats(pid,from,t);if(lf(pid,null,from,t).length){const g=goals(pid),wks=Math.max(1,wk.days/7);pd.h2('Stil de viață (30 de zile)');pd.kv([['Mișcare',`${r0(wk.actMin/wks)} min/săptămână (țintă ${g.act})`],['Alcool',wk.alcN?`${r1(wk.alcU/wks)} unități/săptămână`:''],['Somn',wk.sleepN?r1(wk.sleep)+' h/noapte':''],['Apă',wk.waterD?r0(wk.water)+' ml/zi':''],['Pași',wk.stepsN?r0(wk.steps)+'/zi':'']].filter(x=>x[1]))}
 pd.h2('Notițe din consultație');pd.box(' \n \n \n \n \n \n \n \n',[245,248,250]);return pd.finish()}
