const QLG=[['Hemoleucogramă',['Leucocite','Eritrocite','Hemoglobină','Hematocrit','VEM (MCV)','HEM (MCH)','CHEM (MCHC)','Trombocite','Neutrofile %','Limfocite %','Monocite %','Eozinofile %','Bazofile %','Neutrofile (abs.)','Limfocite (abs.)','Monocite (abs.)','Eozinofile (abs.)','Bazofile (abs.)']],['Lipide',['Colesterol total','HDL colesterol','LDL colesterol','Trigliceride']],['Glicemie și rinichi',['Glicemie à jeun','Hemoglobină glicată (HbA1c)','Creatinină','eGFR (CKD-EPI)','Uree','Acid uric','Albumină urinară','Creatinină urinară']],['Ficat',['TGO (AST)','TGP (ALT)','GGT','Bilirubină totală']],['Electroliți',['Sodiu','Potasiu','Calciu','Magneziu']],['Altele',['TSH','FT4','Fier seric','Feritină','Vitamina D (25-OH)','Vitamina B12','Proteina C reactivă (CRP)','VSH','INR','PSA total']]];
function labQuick(){if(!P())return;const sx=P().sex,dg=document.createElement('dialog');dg.className='qlab';let n=0;
 dg.innerHTML=`<form method="dialog"><div class="eh"><b>⚡ Analize: introducere rapidă</b></div><label class="w">Data recoltării<input type="date" name="date" value="${today()}" required></label><label class="w">Laborator / medic (opțional)<input name="lab" placeholder="ex. Sf. Maria"></label><small class="mu">Completează doar ce ai pe hârtie, restul lasă-l gol. Intervalele de referință sunt cele din aplicație (orientative).</small>${QLG.map(([g,ts],gi)=>`<details class="card"${gi<2?' open':''}><summary>${g}</summary>${ts.map(t=>{const d=labDef(t,sx);if(!d)return'';const r=labRef({lo:d.lo,hi:d.hi});return`<label class="ql"><span>${esc(t)}<small>${r?'ref '+r+' ':''}${esc(d.u)}</small></span><input name="q${n++}" data-t="${esc(t)}" inputmode="decimal" autocomplete="off"></label>`}).join('')}</details>`).join('')}<div class="stickyact"><button type="button" class="btn s" data-x="1">Anulează</button><button class="btn">Salvează valorile</button></div></form>`;
 document.body.appendChild(dg);dg.showModal();dg.addEventListener('close',()=>dg.remove());
 dg.querySelector('[data-x]').onclick=()=>{dg.close()};
 dg.querySelector('form').onsubmit=e=>{e.preventDefault();const f=e.target,date=f.date.value||today(),lab=(f.lab.value||'').trim();let c=0,bad=[];
  dg.querySelectorAll('input[data-t]').forEach(i=>{const raw=i.value.trim().replace(',','.');if(!raw)return;const v=+raw;if(!Number.isFinite(v)||v<0){bad.push(i.dataset.t);return}const d=labDef(i.dataset.t,sx);data.labs.push({id:id(),pid,date,lab,t:i.dataset.t,v,u:d.u,lo:d.lo==null?'':d.lo,hi:d.hi==null?'':d.hi});c++});
  if(bad.length)return alert('Valoare invalidă la: '+bad.join(', '));if(!c)return alert('Nu ai completat nicio valoare.');dg.close();save();toast(c+' valori salvate',()=>{})}}
const _lab=DOS.lab;DOS.lab=()=>`<div class="card"><button class="btn" data-qlab="1">⚡ Introdu rapid analize (mai multe valori)</button><small class="mu" style="display:block;margin-top:8px">Cea mai sigură cale: copiezi valorile de pe hârtie într-un singur formular.</small></div>`+_lab();
