const dleft=d=>Math.round((dts(d)-dts(today()))/864e5);
function dchip(d){const n=dleft(d),c=n<0?'hot':n<=1?'hot':n<=7?'mid':'good';return`<span class="chip ${c}">${n<0?'depășită cu '+(-n)+' zile':n===0?'azi':n===1?'mâine':'în '+n+' zile'}</span>`}
