 if(d.ap){const pre={};if(d.apk){pre.kind=d.apk;pre.title=AK[d.apk][1]}if(d.apsp!==undefined){const n=specs()[+d.apsp];if(n)pre.sp=n}apptForm(d.ap==='new'?null:data.appts.find(x=>x.id===d.ap),d.ap==='new'?pre:null)}
