/* ===== src/spec.js ===== */
/* Sănătate · Dosar pe specialități: rezumat, secțiuni, PDF, gestionare în Setări */
const SPDEF=['Cardiologie','Endocrinologie','Gastro / ficat','ORL','Medicină de familie'],SPGEN='General / alte',
nrm=s=>String(s||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,''),
specs=()=>Array.isArray(data.settings.specs)?data.settings.specs:SPDEF,
spAll=()=>[...specs(),SPGEN],
/* cuvinte-cheie pentru asocierea automată: [fragment din numele specialității, regex pe text fără diacritice] */
SPKW=[['cardi',/cardi|hipertens|\bhta\b|ekg|ecg|colesterol|ldl|hdl|trigliceride|tensiune|aritm|angin|infarct|palpitat|\bi1\d\b|^453/],
['endocrin',/endocrin|diabet|glicemie|glucoz|hba1c|glicat|\btsh\b|\bft4\b|tiroid|vitamina d|insulin|obezit/],
['gastro',/gastro|hepat|ficat|steato|\bggt\b|\bgama\b|\btgo\b|\btgp\b|\bast\b|\balt\b|bilirubin|reflux|colon|digest/],
['orl',/\borl\b|otorino|otita|sinuz|rinit|amigdal|faring|laring|auz|nazal/],
['famil',/medic de familie|medicina de familie|\bmf\b/]];
function spMatch(text){const t=nrm(text);if(!t.trim())return null;const L=specs();
 let s=L.find(n=>{const k=nrm(n);return k.length>=3&&(k.length<=4?new RegExp('\\b'+k.replace(/[^a-z0-9]/g,'')+'\\b').test(t):t.includes(k))});if(s)return s;
 s=L.find(n=>{const k=nrm(n).split(/[^a-z0-9]+/)[0];return k.length>=5&&t.includes(k.slice(0,5))});if(s)return s;
 for(const[k,rx]of SPKW){if(rx.test(t)){const f=L.find(n=>nrm(n).includes(k));if(f)return f}}return null}
const SPTXT={labs:x=>x.t,dx:x=>[x.name,x.code,x.doctor].join(' '),visits:x=>[x.spec,x.doctor,x.reason].join(' '),appts:x=>[x.title,x.doctor,x.place,x.note].join(' '),docs:x=>[x.spec,x.title,x.doctor].join(' ')};
function spOf(k,x){if(x.sp&&(x.sp===SPGEN||specs().includes(x.sp)))return x.sp;return spMatch(SPTXT[k](x))||SPGEN}
function spItems(name){const f=(k,w)=>data[k].filter(x=>x.pid===pid&&(!w||w(x))&&spOf(k,x)===name);
 return{dx:f('dx').sort((a,b)=>(a.status==='rezolvat')-(b.status==='rezolvat')||(b.date||'').localeCompare(a.date||'')),vis:f('visits',x=>!x.planned).sort((a,b)=>b.date.localeCompare(a.date)),
 labs:f('labs').sort((a,b)=>b.date.localeCompare(a.date)||a.t.localeCompare(b.t)),docs:f('docs').sort((a,b)=>(b.date||'').localeCompare(a.date||''))}}
const spN=n=>{const i=spItems(n);return i.dx.length+i.vis.length+i.labs.length+i.docs.length},
spNote=n=>((data.settings.spn||{})[n]||'').trim(),
spOpts=()=>[['','Automat (după conținut)'],...spAll().map(n=>[n,n])],
lastPerTest=L=>{const m={};[...L].sort((a,b)=>a.date.localeCompare(b.date)).forEach(x=>m[x.t]=x);return Object.values(m)},
lflag=x=>{const f=labFlag(x);return f==='H'?['↑ crescut','hot']:f==='L'?['↓ scăzut','hot']:f==='N'?['în limite','good']:['','']};
let dosSp='';
/* ---------- ecranul Rezumat / specialități ---------- */
function spCard(n,i){const c=spItems(n),z=c.labs.filter(x=>labFlag(x)==='H'||labFlag(x)==='L'),lt=lastPerTest(c.labs).filter(x=>labFlag(x)==='H'||labFlag(x)==='L').length;
 return`<button class="spc" data-sp="${i}"><b>${esc(n)}</b><small>${c.dx.length} diagnostice · ${c.vis.length} consultații</small><small>${lt?`<span style="color:var(--er)">${lt} ${lt===1?"analiză":"analize"} în afara limitelor</span>`:`${lastPerTest(c.labs).length} analize`} · ${c.docs.length} documente</small></button>`}
DOS.sum=function(){if(dosSp!==''){const n=spAll()[+dosSp];if(n)return spPage(n,+dosSp);dosSp=''}
 const p=P(),a=age(p),dxa=data.dx.filter(x=>x.pid===pid&&x.status!=='rezolvat'),ms=data.meds.filter(m=>m.pid===pid&&!m.prn&&(!m.end||m.end>=today())),
 out=lastPerTest(data.labs.filter(x=>x.pid===pid)).filter(x=>labFlag(x)==='H'||labFlag(x)==='L'),up=upcoming(pid).slice(0,3),gen=spN(SPGEN);
 return`<div class="card"><h2>${esc(pname(p))}${a!=null?` <small class="mu" style="font-weight:500">${a} ani</small>`:''}</h2>
 ${p.allergies?`<div class="warn hot" style="margin:0 0 10px">⚠ Alergii / intoleranțe: ${esc(p.allergies)}</div>`:''}
 <div class="acts2"><button class="btn" data-sppdf="all">📄 PDF dosar complet</button><button class="btn s" data-pdf="emerg">🆘 Fișă urgență</button></div></div>
 <div class="card"><h2>Afecțiuni active</h2>${dxa.map(x=>`<div class="row"><span>${esc(x.name)}${x.code?` <small style="display:inline">(${esc(x.code)})</small>`:''}<small>${esc(spOf('dx',x))}${x.date?' · din '+fmtD(x.date):''}</small></span></div>`).join('')||'<div class="empty">Niciun diagnostic activ.</div>'}</div>
 <div class="card"><h2>Tratament curent</h2>${ms.map(m=>`<div class="row"><span>${esc(m.name)} <small style="display:inline">${esc(m.dose||'')}</small><small>${(m.times||[]).join(' · ')}</small></span></div>`).join('')||'<div class="empty">Niciun medicament activ.</div>'}</div>
 ${out.length?`<div class="card"><h2>Valori în afara limitelor <small class="mu" style="font-weight:500">(cele mai recente)</small></h2>${out.map(x=>{const[t,c]=lflag(x);return`<div class="row"><span>${esc(x.t)}<small>${fmtD(x.date)} · ${esc(spOf('labs',x))}</small></span><span><b>${x.v}</b> <small style="display:inline">${esc(x.u||'')}</small> <span class="chip ${c}">${t}</span></span></div>`}).join('')}<small class="mu">Discută-le cu medicul. Aplicația nu pune diagnostice.</small></div>`:''}
 ${up.length?`<div class="card"><h2>Programări următoare</h2>${up.map(u=>`<div class="row"><span>${esc(u.title)}<small>${esc(u.sub)}</small></span><b>${fmtD(u.date)}${u.time?' '+u.time:''}</b></div>`).join('')}</div>`:''}`};
function spPage(n,i){const c=spItems(n),note=spNote(n),L=lastPerTest(c.labs),dts=[...new Set(c.labs.map(x=>x.date))];
 return`<button class="btn s m" data-sp="" style="margin-bottom:10px">‹ Toate specialitățile</button>
 <div class="card"><h2>${esc(n)} <button class="btn m" data-sppdf="${i}" style="float:right">📄 PDF</button></h2>
 ${note?`<p style="white-space:pre-wrap;margin:0 0 8px">${esc(note)}</p>`:'<small class="mu">Poți nota aici ce e important la această specialitate (medic, ce urmărești, ce ai de făcut).</small>'}
 <div class="acts2" style="margin-top:8px"><button class="btn s m" data-spn="${i}">✎ Notă</button><button class="btn s m" data-ap="new" data-apsp="${i}">＋ Programare</button><button class="btn s m" data-dx="new">＋ Diagnostic</button><button class="btn s m" data-vis="new">＋ Consultație</button><button class="btn s m" data-lab="new">＋ Analiză</button><button class="btn s m" data-doc="new">＋ Document</button></div></div>
 ${(a=>a.length?`<div class="card"><h2>📅 Programări</h2>${a.map(x=>apptRow(x,1)).join('')}</div>`:'')(data.appts.filter(x=>x.pid===pid&&!x.done&&x.date>=today()&&spOf('appts',x)===n).sort((a,b)=>a.date.localeCompare(b.date)))}
 <div class="card"><h2>Diagnostice</h2>${c.dx.map(x=>`<div class="row"><div><b>${esc(x.name)}</b>${x.code?` <small style="display:inline">(${esc(x.code)})</small>`:''} <span class="chip ${x.status==='rezolvat'?'good':'mid'}">${x.status==='rezolvat'?'Rezolvat':'Activ'}</span><small>${x.date?fmtD(x.date):''}${x.doctor?' · '+esc(x.doctor):''}</small>${x.note?`<small>${esc(x.note)}</small>`:''}</div><div class="ac"><button class="btn s m" data-dx="${x.id}">✎</button><button class="btn d" data-ddx="${x.id}" aria-label="Șterge">✕</button></div></div>`).join('')||'<div class="empty">Niciun diagnostic.</div>'}</div>
 <div class="card"><h2>Consultații</h2>${c.vis.map(x=>`<div class="row"><div><b>${fmtD(x.date)}</b><small>${esc(x.doctor||'')}${x.reason?' · '+esc(x.reason):''}</small>${x.concl?`<small style="white-space:pre-wrap;color:var(--tx)">${esc(x.concl)}</small>`:''}${x.next?`<small>Următorul control: <b>${fmtD(x.next)}</b></small>`:''}</div><div class="ac"><button class="btn s m" data-vis="${x.id}">✎</button><button class="btn d" data-dvis="${x.id}" aria-label="Șterge">✕</button></div></div>`).join('')||'<div class="empty">Nicio consultație.</div>'}</div>
 <div class="card"><h2>Analize <small class="mu" style="font-weight:500">${L.length?'ultimele valori':''}</small></h2>${L.sort((a,b)=>(labFlag(a)==='N')-(labFlag(b)==='N')||a.t.localeCompare(b.t)).map(x=>{const[t,cl]=lflag(x);return`<div class="row"><div><b>${esc(x.t)}</b><small>${fmtD(x.date)} · referință ${labRef(x)||'—'} ${esc(x.u||'')}${c.labs.filter(y=>y.t===x.t).length>1?` · ${c.labs.filter(y=>y.t===x.t).length} valori`:''}</small></div><div class="ac"><span><b>${x.v}</b> <small style="display:inline">${esc(x.u||'')}</small></span>${t?`<span class="chip ${cl}">${t}</span>`:''}<button class="btn s m" data-splab="${esc(x.t)}" aria-label="Grafic și istoric">📈</button><button class="btn s m" data-lab="${x.id}">✎</button></div></div>`}).join('')||'<div class="empty">Nicio analiză.</div>'}${dts.length>1?`<small class="mu">${dts.length} date de recoltare. Istoricul complet e în PDF și la 📈.</small>`:''}</div>
 <div class="card"><h2>Documente</h2>${c.docs.map(x=>`<div class="row"><div><b>${esc(x.title)}</b> <span class="chip mid">${DOCK[x.kind]||''}</span><small>${x.date?fmtD(x.date):''}${x.doctor?' · '+esc(x.doctor):''}</small>${x.note?`<small>${esc(x.note)}</small>`:''}${(x.files||[]).length?`<div class="thumbs">${x.files.map((f,j)=>f.pdf||f.gen?`<button class="th pdf" data-view="${x.id}|${j}">${f.pdf?'PDF':esc((f.ext||'fișier').toUpperCase())}<small>${esc(f.name)}</small></button>`:`<button class="th" data-view="${x.id}|${j}"><img data-th="${f.id}" alt="${esc(f.name)}"></button>`).join('')}</div>`:''}</div><div class="ac"><button class="btn s m" data-doc="${x.id}">✎</button></div></div>`).join('')||'<div class="empty">Niciun document.</div>'}</div>`}
/* ---------- PDF ---------- */
function specSection(pd,n,brief){const c=spItems(n),note=spNote(n);if(!c.dx.length&&!c.vis.length&&!c.labs.length&&!c.docs.length&&!note)return false;pd.h2(n);if(note)pd.p(note,9.5);
 if(c.dx.length){pd.p('Diagnostice',10,pd.TEAL,1);pd.table(['Diagnostic','Cod','Din','Stare','Medic'],c.dx.map(x=>[{t:x.name,b:1},x.code||'',x.date?fmtD(x.date):'',x.status==='rezolvat'?'Rezolvat':'Activ',x.doctor||'']),[6,1.5,2,1.8,3])}
 if(c.vis.length){pd.p('Consultații',10,pd.TEAL,1);pd.table(['Data','Medic','Motiv și concluzii','Control'],c.vis.map(x=>[fmtD(x.date),x.doctor||'',[x.reason,x.concl].filter(Boolean).join(' — '),x.next?fmtD(x.next):'']),[2,3.5,8,2])}
 if(c.labs.length){const lt=x=>{const f=labFlag(x);return f==='H'?{t:'↑ crescut',b:1,c:[200,30,50]}:f==='L'?{t:'↓ scăzut',b:1,c:[200,30,50]}:{t:'în limite',c:[20,120,80]}},rows=brief?lastPerTest(c.labs).sort((a,b)=>(labFlag(a)==='N')-(labFlag(b)==='N')||a.t.localeCompare(b.t)):c.labs;
  pd.p(brief?'Analize: ultimele valori':'Analize: tot istoricul',10,pd.TEAL,1);pd.table(['Data','Analiza','Valoare','Referință','Stare'],rows.map(x=>[fmtD(x.date),x.t,{t:`${x.v} ${x.u||''}`,b:1},labRef(x)+' '+(x.u||''),lt(x)]),[2,5,2.5,3,2.2])}
 if(c.docs.length){pd.p('Documente',10,pd.TEAL,1);pd.table(['Data','Document','Tip','Fișiere'],c.docs.map(x=>[x.date?fmtD(x.date):'',{t:x.title,b:1},DOCK[x.kind]||'',String((x.files||[]).length)]),[2,7,3,1.5]);if(!brief)c.docs.filter(x=>x.text).forEach(x=>{pd.p('Text din: '+x.title,9,pd.TEAL,1);pd.p(x.text.slice(0,2500),8.5)})}
 if(/cardi/.test(nrm(n))){const to=today(),bs=pbp(pid,addD(to,-89),to);if(bs.length){const s=bpStats(bs,pid);pd.p('Tensiune arterială (ultimele 90 de zile)',10,pd.TEAL,1);pd.kv([['Măsurători',String(s.n)],['Medie',`${r0(s.sys)}/${r0(s.dia)} mmHg`],['Sistolică min–max',`${s.smin}–${s.smax}`],['Diastolică min–max',`${s.dmin}–${s.dmax}`]])}}
 return true}
async function buildSpecPdf(which){await loadPdf();const p=P(),a=age(p),full=which==='all',n=full?null:spAll()[+which],pd=new Pdf(`Sănătate · ${pname(p)} · ${fmtD(today())}`),w=vlast(pid,'weight');
 pd.title(full?'Dosar medical · rezumat':'Dosar medical · '+n,`${pname(p)} · generat ${fmtD(today())}`);
 pd.kv([['Pacient',pname(p)],['Sex',SEX[p.sex]],['Data nașterii',p.born?fmtD(p.born)+(a!=null?` (${a} ani)`:''):''],['Înălțime',p.height?p.height+' cm':''],['Greutate',w?`${w.v} kg (${fmtD(w.date)})`:''],['Grupa de sânge',p.blood],['Medic de familie',[p.doctor,p.dphone].filter(Boolean).join(' · ')],['Asigurare',p.ins]]);
 if(p.allergies)pd.box('Alergii / intoleranțe: '+p.allergies);
 if(full){const dxa=data.dx.filter(x=>x.pid===pid&&x.status!=='rezolvat'),ms=data.meds.filter(m=>m.pid===pid&&!m.prn&&(!m.end||m.end>=today())),out=lastPerTest(data.labs.filter(x=>x.pid===pid)).filter(x=>labFlag(x)==='H'||labFlag(x)==='L');
  if(dxa.length){pd.h2('Afecțiuni active');pd.table(['Diagnostic','Cod','Specialitate','Din'],dxa.map(x=>[{t:x.name,b:1},x.code||'',spOf('dx',x),x.date?fmtD(x.date):'']),[6,1.5,3,2])}
  if(ms.length){pd.h2('Tratament curent');pd.table(['Medicament','Doză','Ore','Din'],ms.map(m=>[{t:m.name,b:1},m.dose||'',(m.times||[]).join(', '),m.start?fmtD(m.start):'']),[5,3,3,2])}
  if(out.length){pd.h2('Valori în afara limitelor (cele mai recente)');pd.table(['Analiza','Valoare','Referință','Data','Specialitate'],out.map(x=>[{t:x.t,b:1,c:[200,30,50]},{t:`${x.v} ${x.u||''}`,b:1},labRef(x)+' '+(x.u||''),fmtD(x.date),spOf('labs',x)]),[4,2.5,3,2,3])}
  spAll().forEach(s=>specSection(pd,s,true))}
 else if(!specSection(pd,n,false)){pd.h2(n);pd.p('Nimic înregistrat la această specialitate.',10)}
 return pd.finish()}
async function sendPdf(blob,name){const file=new File([blob],name,{type:'application/pdf'});try{if(navigator.canShare&&navigator.canShare({files:[file]})){await navigator.share({files:[file],title:name});return}}catch(e){if(e&&e.name==='AbortError')return}dl(name,blob,'application/pdf')}
/* ---------- gestionare în Setări ---------- */
function spSettings(){return`<div class="card"><h2>Specialități în Dosar</h2><small class="mu">Dosarul se împarte pe aceste secțiuni. Adaugă oricând altele (dermatologie, ortopedie, stomatologie…).</small>${specs().map((n,i)=>`<div class="row"><span>${esc(n)}<small>${spN(n)} înregistrări</small></span><span class="ac"><button class="btn s m" data-spren="${i}">✎</button><button class="btn d" data-spdel="${i}" aria-label="Șterge">✕</button></span></div>`).join('')}<div class="acts2" style="margin-top:10px"><button class="btn m" data-spadd="1">＋ Adaugă specialitate</button>${Array.isArray(data.settings.specs)?'<button class="btn s m" data-sprst="1">Revino la lista inițială</button>':''}</div></div>`}
document.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;const d=t.dataset;
 if(d.sp!==undefined){dosSp=d.sp;dosTab='sum';render();scrollTo(0,0)}
 else if(d.splab!==undefined){labSel=d.splab;dosTab='lab';dosSp='';render();scrollTo(0,0)}
 else if(d.sppdf!==undefined){const b0=t.textContent;t.disabled=true;t.textContent='Se creează…';(async()=>{try{const nm=d.sppdf==='all'?'dosar':spAll()[+d.sppdf];const blob=await buildSpecPdf(d.sppdf);await sendPdf(blob,`${nm.replace(/[^\wăâîșțĂÂÎȘȚ]+/g,'-')}-${pname(P()).replace(/\W+/g,'-')}-${today()}.pdf`)}catch(err){alert('PDF nereușit: '+(err.message||err))}finally{t.disabled=false;t.textContent=b0}})()}
 else if(d.spn!==undefined){const n=spAll()[+d.spn];ask('Notă: '+n,[{n:'t',l:'Notă pentru această specialitate',t:'area',v:spNote(n),w:1}],v=>{data.settings.spn={...(data.settings.spn||{}),[n]:(v.t||'').trim()};save()})}
 else if(d.spadd){ask('Specialitate nouă',[{n:'n',l:'Nume',req:1,w:1,ph:'ex. Dermatologie'}],v=>{const n=(v.n||'').trim();if(!n)return false;if(spAll().some(x=>nrm(x)===nrm(n))){alert('Există deja o specialitate cu acest nume.');return false}data.settings.specs=[...specs(),n];save();toast('Specialitate adăugată')})}
 else if(d.spren!==undefined){const i=+d.spren,o=specs()[i];ask('Redenumește specialitatea',[{n:'n',l:'Nume',v:o,req:1,w:1}],v=>{const n=(v.n||'').trim();if(!n)return false;if(n!==o&&spAll().some(x=>nrm(x)===nrm(n))){alert('Există deja o specialitate cu acest nume.');return false}const L=[...specs()];L[i]=n;data.settings.specs=L;['labs','dx','visits','docs'].forEach(k=>data[k].forEach(x=>{if(x.sp===o)x.sp=n}));if(data.settings.spn&&data.settings.spn[o]!==undefined){data.settings.spn[n]=data.settings.spn[o];delete data.settings.spn[o]}save()})}
 else if(d.spdel!==undefined){const i=+d.spdel,o=specs()[i];if(!confirm(`Ștergi specialitatea „${o}”?\nÎnregistrările nu se șterg: ele se mută automat la altă specialitate potrivită sau la „${SPGEN}”.`))return;data.settings.specs=specs().filter((_,j)=>j!==i);['labs','dx','visits','docs'].forEach(k=>data[k].forEach(x=>{if(x.sp===o)x.sp=''}));dosSp='';save();toast('Specialitate ștearsă')}
 else if(d.sprst){if(!confirm('Revii la lista inițială de specialități? Înregistrările rămân.'))return;delete data.settings.specs;dosSp='';save()}});
document.addEventListener('change',e=>{if(e.target.id==='lsel'){labSel=e.target.value;render()}});

