 $('title').textContent=NAV.find(n=>n[0]===g)[1];const ps=$('psel');ps.innerHTML=data.patients.map(p=>`<option value="${p.id}"${p.id===pid?' selected':''}>${esc(pname(p))}</option>`).join('');ps.hidden=data.patients.length<1;
