const num=v=>v===''||v==null?null:Number(v),
bpFields=x=>[{n:'sys',l:'Sistolică',t:'number',v:x.sys,req:1,im:'numeric'},{n:'dia',l:'Diastolică',t:'number',v:x.dia,req:1,im:'numeric'},{n:'pulse',l:'Puls',t:'number',v:x.pulse||'',im:'numeric'},{n:'date',l:'Data',t:'date',v:x.date,req:1},{n:'time',l:'Ora',t:'time',v:x.time,req:1},{n:'arm',l:'Braț',t:'select',v:x.arm,o:[['st','Stâng'],['dr','Drept']]},{n:'pos',l:'Poziție',t:'select',v:x.pos,o:[['sed','Șezând'],['cul','Culcat'],['pic','În picioare']]},{n:'tags',l:'Context',t:'tags',v:x.tags||[]},{n:'note',l:'Notă',v:x.note||'',w:1}];
function bpOk(v){const s=+v.sys,d=+v.dia,p=v.pulse===''||v.pulse==null?null:+v.pulse;if(!(s>=50&&s<=300&&d>=30&&d<=200)){alert('Valori nerealiste. Sistolica trebuie să fie 50–300 și diastolica 30–200.');return false}if(s<=d){alert('Sistolica (mare) trebuie să fie mai mare decât diastolica (mică).');return false}if(p!=null&&!(p>=20&&p<=250)){alert('Pulsul trebuie să fie între 20 și 250.');return false}return true}
