function medForm(m){const o=m||{};ask(m?'Editează medicamentul':'Medicament nou',[{n:'name',l:'Denumire',v:o.name||'',req:1,w:1,ph:'ex. Amlodipină'},{n:'dose',l:'Doză',v:o.dose||'',ph:'ex. 5 mg'},{n:'prn',l:'Doză la nevoie (fără ore fixe)',t:'check',v:o.prn},{n:'times',l:'Ore (până la 6)',t:'times',v:o.times||['08:00']},{n:'days',l:'Zile',t:'days',v:o.days&&o.days.length?o.days:null},{n:'start',l:'Începe la',t:'date',v:o.start||today()},{n:'end',l:'Se oprește la (opțional)',t:'date',v:o.end||''},{n:'stock',l:'Pastile rămase (opțional, scade singură la bifare)',t:'number',v:o.stock??'',im:'numeric',min:0},{n:'note',l:'Notă',v:o.note||'',w:1}],v=>{
 if(!v.name.trim())return false;if(!v.prn&&!v.times.length){alert('Alege cel puțin o oră sau bifează „la nevoie”.');return false}if(v.end&&v.end<v.start){alert('Data de oprire este înaintea datei de început.');return false}
 const t=today(),days=v.days.length===7||!v.days.length?[]:v.days,times=v.prn?[]:v.times,x=m||{id:id(),pid};const ch=!m||JSON.stringify(x.times)!==JSON.stringify(times)||x.start!==v.start;
 Object.assign(x,{name:v.name.trim(),dose:v.dose.trim(),prn:!!v.prn,times,days,start:v.start,end:v.end||'',note:v.note.trim(),stock:v.stock===''||v.stock==null?null:Math.max(0,+v.stock)});if(ch)x.from=v.start<t?v.start+'T00:00':t+'T'+nowT();if(!m)data.meds.push(x);save()})}
function icsText(){const p=P(),t=today(),L=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Sanatate//RO','CALSCALE:GREGORIAN'],z=s=>s.replace(/-/g,''),dt=(d,h)=>z(d)+'T'+h.replace(':','')+'00',BD=['SU','MO','TU','WE','TH','FR','SA'];
 const ev=(sum,h,days,start,end,desc)=>{let d=start>t?start:t;for(let i=0;i<7&&days.length&&!days.includes(dow(d));i++)d=addD(d,1);
  L.push('BEGIN:VEVENT','UID:'+id()+'@tensiunea-mea','DTSTAMP:'+z(t)+'T000000','DTSTART:'+dt(d,h),'DTEND:'+dt(d,hm(mins(h)+10)),'RRULE:FREQ='+(days.length?'WEEKLY;BYDAY='+days.map(i=>BD[i]).join(','):'DAILY')+(end?';UNTIL='+z(end)+'T235959':''),'SUMMARY:'+sum,'DESCRIPTION:'+desc,'BEGIN:VALARM','TRIGGER:PT0M','ACTION:DISPLAY','DESCRIPTION:'+sum,'END:VALARM','END:VEVENT')};
 data.meds.filter(m=>m.pid===pid&&!m.prn&&(!m.end||m.end>=t)).forEach(m=>(m.times||[]).forEach(h=>ev('💊 '+m.name+' '+(m.dose||'')+' ('+p.name+')',h,m.days||[],m.start||t,m.end,'Pastilă programată')));
 const one=(sum,d,h,desc)=>{if(!d||d<t)return;h=h||'09:00';L.push('BEGIN:VEVENT','UID:'+id()+'@tensiunea-mea','DTSTAMP:'+z(t)+'T000000','DTSTART:'+dt(d,h),'DTEND:'+dt(d,hm(mins(h)+60)),'SUMMARY:'+sum,'DESCRIPTION:'+desc,'BEGIN:VALARM','TRIGGER:-P1D','ACTION:DISPLAY','DESCRIPTION:'+sum,'END:VALARM','BEGIN:VALARM','TRIGGER:-PT1H','ACTION:DISPLAY','DESCRIPTION:'+sum,'END:VALARM','END:VEVENT')};
 data.docs.filter(x=>x.pid===pid&&x.appt).forEach(x=>one('🏥 Programare '+(x.spec||x.title)+' ('+pname(p)+')',x.appt,x.apptT,x.title));
 data.visits.filter(x=>x.pid===pid&&x.next).forEach(x=>one('🩺 Control '+(x.spec||x.doctor||'')+' ('+pname(p)+')',x.next,'09:00','Control recomandat'));
 data.prev.filter(x=>x.pid===pid).forEach(x=>{const n=pnext(x);if(n)one((PK[x.kind]||'🛡️')+' '+x.name+' ('+pname(p)+')',n,'09:00',x.note||'Memento prevenție')});
 data.appts.filter(x=>x.pid===pid&&!x.done).forEach(x=>one((AK[x.kind]||AK.alta)[0]+' '+x.title+' ('+pname(p)+')',x.date,x.time,[x.place,x.doctor,x.note].filter(Boolean).join(' · ')||'Programare'));
 data.visits.filter(x=>x.pid===pid&&x.planned).forEach(x=>one('👨‍⚕️ Vizită '+(x.spec||x.doctor||'medic')+' ('+pname(p)+')',x.date,x.time||'09:00',x.qs||'Vizită la medic'));
 (p.remind||[]).forEach(h=>ev('❤️ Măsoară tensiunea ('+p.name+')',h,[],t,'','Măsurare tensiune'));L.push('END:VCALENDAR');return L.join('\r\n')}
function validate(j){if(!j||typeof j!=='object'||Array.isArray(j))return{err:'Fișierul nu este un backup Sănătate.'};if(!Array.isArray(j.patients))return{err:'Lipsește lista de pacienți. Nu este un backup Sănătate.'};
 const ids=new Set(j.patients.filter(p=>p&&p.id).map(p=>p.id));let bad=0;const g=(k,f)=>(Array.isArray(j[k])?j[k]:[]).filter(x=>{const ok=x&&typeof x==='object'&&x.id&&ids.has(x.pid)&&f(x);if(!ok)bad++;return ok});
 const out={...j,patients:j.patients.filter(p=>p&&p.id&&typeof p.name==='string'),bp:g('bp',x=>Number.isFinite(+x.sys)&&Number.isFinite(+x.dia)&&/^\d{4}-\d{2}-\d{2}$/.test(x.date||'')),meds:g('meds',x=>typeof x.name==='string'),intakes:g('intakes',x=>/^\d{4}-\d{2}-\d{2}$/.test(x.date||'')),vit:g('vit',x=>Number.isFinite(+x.v)),life:g('life',x=>typeof x.k==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(x.date||'')),dx:g('dx',x=>typeof x.name==='string'),labs:g('labs',x=>Number.isFinite(+x.v)&&typeof x.t==='string'),docs:g('docs',x=>Array.isArray(x.files)),visits:g('visits',x=>/^\d{4}-\d{2}-\d{2}$/.test(x.date||'')),prev:g('prev',x=>typeof x.name==='string'),appts:g('appts',x=>/^\d{4}-\d{2}-\d{2}$/.test(x.date||''))};return{out,bad}}
function mergeFile(j){if(!P())return alert('Creează mai întâi un profil.');const K=['labs','dx','visits','prev','appts'],cnt=K.map(k=>[k,(Array.isArray(j[k])?j[k]:[]).filter(x=>x&&x.id&&!data[k].some(y=>y.id===x.id)).length]),tot=cnt.reduce((a,b)=>a+b[1],0);
 if(!tot)return alert('Datele din acest fișier sunt deja în aplicație.');
 if(!confirm(`Adaug în profilul „${pname(P())}”:\n${cnt.filter(c=>c[1]).map(c=>'• '+({labs:'analize',dx:'diagnostice',visits:'consultații',prev:'prevenție',appts:'programări'})[c[0]]+': '+c[1]).join('\n')}\n\nNu se șterge și nu se înlocuiește nimic din ce ai deja.`))return;
 K.forEach(k=>(Array.isArray(j[k])?j[k]:[]).forEach(x=>{if(x&&x.id&&!data[k].some(y=>y.id===x.id))data[k].push({...x,pid})}));save();toast(`${tot} înregistrări adăugate`);render()}
function importFile(f){if(!f)return;const r=new FileReader();r.onload=()=>{let j;try{j=JSON.parse(r.result)}catch{return alert('Fișierul nu este JSON valid.')}if(j&&j.__merge)return mergeFile(j);const v=validate(j);if(v.err)return alert(v.err);const o=v.out,files=Array.isArray(j.__files)?j.__files:[];delete o.__files;
 if(confirm(`Backup: ${o.patients.length} pacienți, ${o.bp.length} măsurători, ${o.meds.length} medicamente.\nÎn aplicație acum: ${data.patients.length} pacienți, ${data.bp.length} măsurători.${files.length?`\n${files.length} fișiere (poze/documente) vor fi restaurate.`:''}${v.bad?`\n⚠ ${v.bad} înregistrări invalide vor fi ignorate.`:''}\n\nÎnlocuiești datele curente? Se creează automat un instantaneu de siguranță.`))(async()=>{if(files.length)await Files.importAll(files);await Store.replace(o)})().then(()=>location.reload()).catch(e=>alert('Importul a eșuat: '+e.message))};r.readAsText(f)}
const slotOf=k=>{const[mid,t,d]=k.split('|'),m=data.meds.find(x=>x.id===mid);return m?{m,d,t}:null};
