document.addEventListener('submit',e=>{const f=e.target.id;if(f!=='pf'&&f!=='bf')return;e.preventDefault();const v=Object.fromEntries(new FormData(e.target));
 if(f==='pf'){if(!(v.first||'').trim())return;const p={id:id()};savePat(p,{...v,times:[]});data.patients.push(p);setPid(p.id);save()}
 else{if(!bpOk(v))return;const x={id:id(),pid,...bpObj(v),tags:TAGS.map(t=>t[0]).filter(k=>('tg_'+k) in v)};
  if(v.sys2||v.dia2){const w={sys:v.sys2,dia:v.dia2,pulse:v.pulse2};if(!w.sys||!w.dia)return alert('Completează ambele valori ale celei de-a doua măsurători sau lasă-le goale.');if(!bpOk(w))return;const p2=+w.pulse||null;x.note=(x.note?x.note+' · ':'')+`medie din ${v.sys}/${v.dia} și ${w.sys}/${w.dia}`;x.sys=r0((x.sys+ +w.sys)/2);x.dia=r0((x.dia+ +w.dia)/2);x.pulse=x.pulse&&p2?r0((x.pulse+p2)/2):x.pulse||p2}
  data.bp.push(x);tab='home';save();toast(`Salvat: ${x.sys}/${x.dia} · ${catOf(x.sys,x.dia).n}`);if(isCrisis(x))setTimeout(()=>alert(CRISIS),200)}});
try{if(localStorage.getItem('tm-theme')==='d')document.body.classList.add('dark')}catch{}
if(Store.notes().length)setTimeout(()=>toast('⚠ '+Store.notes()[0]),600);
render();window.__booted=true;document.getElementById('splash')?.remove();window.__bmDown&&window.__bmDown();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});
